import{_ as a}from"./chunks/image28.DpoC0mYL.js";import{_ as r,a as l,b as c,c as g,d,e as p,f as h,g as m,h as u,i as A,j as w,k as y,l as f,m as x,n as b,o as v,p as z,q as D,r as _,s as C}from"./chunks/image10.BGNQhF2H.js";import{_ as k,o as H,c as q,ak as i,j as e,a as o,t as E}from"./chunks/framework.Bz66nvfN.js";const Q="/projects/miniHexapro/en/latest/assets/image30.BvxCErfv.webp",B="/projects/miniHexapro/en/latest/assets/image1.BWNuGz6Q.webp",P="data:image/png;base64,",I="/projects/miniHexapro/en/latest/assets/image39.CbDP-G5x.webp",T="/projects/miniHexapro/en/latest/assets/image4.BS7RYPyL.webp",O="/projects/miniHexapro/en/latest/assets/image40.BWS2IjJF.webp",X="/projects/miniHexapro/en/latest/assets/image41.BCSq_JlD.webp",M="/projects/miniHexapro/en/latest/assets/image42.HYLO7xj5.webp",Y="/projects/miniHexapro/en/latest/assets/image8.Bn9XwW2v.webp",F="/projects/miniHexapro/en/latest/assets/image9.BArA-2i0.webp",U="/projects/miniHexapro/en/latest/assets/image10.BGOSFPbx.webp",j="/projects/miniHexapro/en/latest/assets/image11.DBgnzDjD.webp",V="/projects/miniHexapro/en/latest/assets/image12.BnMAFP3E.webp",S="/projects/miniHexapro/en/latest/assets/image13.C5L7qBAT.webp",W="/projects/miniHexapro/en/latest/assets/image14.CklCbzDS.webp",R="/projects/miniHexapro/en/latest/assets/image15.CdxpUeX3.webp",N="/projects/miniHexapro/en/latest/assets/image46.Bj1M4wyH.webp",G="/projects/miniHexapro/en/latest/assets/image17.D-WpV2FH.webp",Z="/projects/miniHexapro/en/latest/assets/image18.ClKEVQdJ.webp",K="/projects/miniHexapro/en/latest/assets/image19.2EVCudw8.webp",L="/projects/miniHexapro/en/latest/assets/image20.DmKaSoxa.webp",J="/projects/miniHexapro/en/latest/assets/image21.a6jM9_Mg.webp",$="/projects/miniHexapro/en/latest/assets/image22.dUCBQMaz.webp",tt="/projects/miniHexapro/en/latest/assets/image43.BA4QhuQ7.webp",et="/projects/miniHexapro/en/latest/assets/image44.D23119m2.webp",it="/projects/miniHexapro/en/latest/assets/image45.CkrH2WNq.webp",ot="/projects/miniHexapro/en/latest/assets/image36.Chg47ugG.webp",st="/projects/miniHexapro/en/latest/assets/image24.DzZmW1Kp.webp",nt="/projects/miniHexapro/en/latest/assets/image2.XOWjlBkt.webp",at="data:image/png;base64,",rt="/projects/miniHexapro/en/latest/assets/image27.DYakroJE.webp",lt="/projects/miniHexapro/en/latest/assets/image19.DAseRU5M.webp",s="/projects/miniHexapro/en/latest/assets/image3.qc_tPXW0.webp",ct="/projects/miniHexapro/en/latest/assets/image27.CZuYSctn.webp",gt="data:image/png;base64,",bt=JSON.parse('{"title":"2. Quick Start","description":"","frontmatter":{},"headers":[],"relativePath":"docs/2. Quick Start.md","filePath":"docs/2. Quick Start.md"}'),dt={name:"docs/2. Quick Start.md"},pt={class:"note custom-block github-alert"};function ht(n,t,mt,ut,At,wt){return H(),q("div",null,[t[10]||(t[10]=i('<h1 id="_2-quick-start" tabindex="-1">2. Quick Start <a class="header-anchor" href="#_2-quick-start" aria-label="Permalink to &quot;2. Quick Start&quot;">​</a></h1><h2 id="_2-1-app-instructions" tabindex="-1">2.1 App Instructions <a class="header-anchor" href="#_2-1-app-instructions" aria-label="Permalink to &quot;2.1 App Instructions&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>miniHexa Pro comes pre-flashed with the factory app remote control program, ready for immediate operation, using Android as an example.</strong></p></div><h3 id="_2-1-1-app-installation" tabindex="-1">2.1.1 App Installation <a class="header-anchor" href="#_2-1-1-app-installation" aria-label="Permalink to &quot;2.1.1 App Installation&quot;">​</a></h3><p>Scan the QR code below to download the app:</p><img loading="lazy" height="500" width="500" src="'+Q+'" class="common_img" style="width:200px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p><strong>Enable Bluetooth and location services in the mobile phone system settings before opening the app.</strong></p></li><li><p><strong>Pair and connect the device via the Bluetooth button inside the app. Do not pair using a PIN code in the mobile phone system settings.</strong></p></li></ul></div><ol><li><p>Set the power switch of miniHexa Pro to <strong>ON</strong>.</p><img loading="lazy" height="600" width="1200" src="'+B+'" class="common_img" style="width:600px;"></li><li><p>Open the <strong>Wonderbot</strong> app. Tap the <img loading="lazy" height="78" width="87" src="'+P+'" class="inline-icon" style="width:60px;"> icon in the upper-left corner to open the robot type selection menu, and select <strong>miniHexa Pro</strong>.</p><img loading="lazy" src="'+I+'" class="common_img" style="width:600px;"></li><li><p>After selection, enter the control interface and tap the flashing <img loading="lazy" height="97" width="87" src="'+T+'" class="inline-icon" style="width:60px;"> icon in the upper-right corner. Locate <strong>miniHexa Pro</strong> in the Bluetooth device list and tap it to connect.</p><img loading="lazy" src="'+O+'" class="common_img" style="width:600px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>If miniHexa Pro does not appear in the list initially, tap &#39;Search Again&#39; to scan for devices.</strong></p></div></li><li><p>Once connected successfully, the Bluetooth icon in the upper-right corner remains solid, and the battery voltage displays on the left.</p><img loading="lazy" height="791" width="1740" src="'+X+'" class="common_img" style="width:600px;"></li></ol><h3 id="_2-1-2-feature-introduction" tabindex="-1">2.1.2 Feature Introduction <a class="header-anchor" href="#_2-1-2-feature-introduction" aria-label="Permalink to &quot;2.1.2 Feature Introduction&quot;">​</a></h3><p>The interface supports motion control, posture adjustment, ultrasonic obstacle avoidance, action group execution, self-balancing, height adjustment, gripper adjustment, and posture reset.</p><p>The interface consists of two main sections, as shown below:</p><img loading="lazy" height="801" width="1733" src="'+M+'" class="common_img" style="width:800px;"><p><strong>1. Menu Bar</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">Icon</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="154" width="173" src="'+Y+'" class="common_img" style="width:80px;"></td><td style="text-align:left;">Returns to the main menu to select a robot type.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="81" width="186" src="'+F+'" class="common_img" style="width:80px;"></td><td style="text-align:left;">Displays the real-time battery voltage of miniHexa Pro.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="133" width="173" src="'+U+'" class="common_img" style="width:80px;"></td><td style="text-align:left;">Video transmission feature, displaying the video feed returned from the visual module.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="119" width="173" src="'+j+'" class="common_img" style="width:80px;"></td><td style="text-align:left;">Bluetooth connection status, flashing when disconnected and staying solid when connected.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="141" width="173" src="'+V+'" class="common_img" style="width:80px;"></td><td style="text-align:left;">Displays additional software and version information.</td></tr></tbody></table><p><strong>2. Control Area</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">Icon</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="548" width="544" src="'+S+'" class="common_img" style="width:80px;"></td><td style="text-align:left;">Controls the omnidirectional movement of miniHexa Pro.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="544" width="546" src="'+W+'" class="common_img" style="width:80px;"></td><td style="text-align:left;">Controls the horizontal planar position of the robot&#39;s center of gravity.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="97" width="549" src="'+R+'" class="common_img" style="width:80px;"></td><td style="text-align:left;">Switches between the <strong>Movement</strong> and <strong>Pose</strong> control tabs.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="179" width="276" src="'+N+'" class="common_img" style="width:80px;"></td><td style="text-align:left;">Displays real-time ultrasonic obstacle distance in centimeters.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="138" width="153" src="'+G+'" class="common_img" style="width:80px;"></td><td style="text-align:left;">Enables or disables ultrasonic obstacle avoidance.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="152" width="170" src="'+Z+'" class="common_img" style="width:80px;"></td><td style="text-align:left;">Controls the Euler angles of miniHexa Pro via the phone gyroscope.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="157" width="166" src="'+K+'" class="common_img" style="width:80px;"></td><td style="text-align:left;">Enables or disables the IMU self-balancing feature.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="152" width="175" src="'+L+'" class="common_img" style="width:80px;"></td><td style="text-align:left;">Opens the action panel to execute preset action groups.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="135" width="143" src="'+J+'" class="common_img" style="width:80px;"></td><td style="text-align:left;">Turns the RGB ultrasonic probe LEDs on or off.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="51" width="260" src="'+$+'" class="common_img" style="width:80px;"></td><td style="text-align:left;">Adjusts the color of the RGB ultrasonic probe LEDs.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="114" width="368" src="'+tt+'" class="common_img" style="width:80px;"></td><td style="text-align:left;">Controls the elevation of the robotic arm.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="117" width="389" src="'+et+'" class="common_img" style="width:80px;"></td><td style="text-align:left;">Controls the opening and closing of the metal gripper.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="50" width="126" src="'+it+'" class="common_img" style="width:80px;"></td><td style="text-align:left;">Resets the robotic arm and metal gripper to their default positions.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="122" width="366" src="'+ot+'" class="common_img" style="width:80px;"></td><td style="text-align:left;">Adjusts the standing height of miniHexa Pro.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="169" width="418" src="'+st+'" class="common_img" style="width:80px;"></td><td style="text-align:left;">Controls left and right turning with the outer buttons, and resets to attention posture with the center button.</td></tr></tbody></table><h3 id="_2-1-3-app-program-flashing-instructions-optional" tabindex="-1">2.1.3 App Program Flashing Instructions - Optional <a class="header-anchor" href="#_2-1-3-app-program-flashing-instructions-optional" aria-label="Permalink to &quot;2.1.3 App Program Flashing Instructions - Optional&quot;">​</a></h3><p>miniHexa Pro comes pre-flashed with the factory app program. Uploading other application programs will overwrite the app control firmware. To restore app control, reflash the factory program as described below:</p><ol><li><p>Connect miniHexa Pro to the computer using a Type-C cable.</p><img loading="lazy" height="800" width="1200" src="'+nt+'" class="common_img" style="width:600px;"></li><li><p>Open the <strong><a href="./.html">02 App Program Files/miniHexaPro_factory/miniHexaPro_factory.ino</a></strong> sketch in the same directory as this document.</p><img loading="lazy" height="28" width="632" src="'+at+'" class="common_img" style="width:800px;"></li><li><p>Select the board model as <strong>ESP32 Dev Module</strong> from the board selection dropdown, as shown below:</p><img loading="lazy" height="39" width="433" src="'+rt+'" class="common_img" style="width:500px;"></li><li><p>Click <strong>Tools</strong> on the menu bar and configure the ESP32 board parameters according to the following image:</p><img loading="lazy" height="785" width="831" src="'+a+'" class="common_img" style="width:800px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Configure the board parameters properly before uploading the sketch.</strong></p></div></li><li><p>Click <strong>Verify</strong> and then click <strong>Upload</strong>. Once the upload completes, the output panel displays the confirmation message shown below, indicating successful flashing:</p><img loading="lazy" height="174" width="1057" src="'+lt+'" class="common_img" style="width:600px;"></li></ol><h2 id="_2-2-large-ai-model-remote-control" tabindex="-1">2.2 Large AI Model Remote Control <a class="header-anchor" href="#_2-2-large-ai-model-remote-control" aria-label="Permalink to &quot;2.2 Large AI Model Remote Control&quot;">​</a></h2><h3 id="_2-2-1-module-power-on" tabindex="-1">2.2.1 Module Power-On <a class="header-anchor" href="#_2-2-1-module-power-on" aria-label="Permalink to &quot;2.2.1 Module Power-On&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Supply power strictly using a 5 V voltage source to avoid damaging the module.</strong></p></div><ol><li><p>Connect one end of the Type-C cable to either of the two Type-C ports on the left side of the module, and connect the other end to a computer USB port.</p><img loading="lazy" height="5128" width="3813" src="'+l+'" class="common_img" style="width:400px;"></li><li><p>Once powered via the cable, the device automatically enters network configuration mode.</p><img loading="lazy" height="446" width="500" src="'+s+'" class="common_img" style="width:400px;"></li></ol><h3 id="_2-2-2-module-network-configuration" tabindex="-1">2.2.2 Module Network Configuration <a class="header-anchor" href="#_2-2-2-module-network-configuration" aria-label="Permalink to &quot;2.2.2 Module Network Configuration&quot;">​</a></h3><ul><li><strong>Operational Steps</strong></li></ul><ol><li><p>Power on the module to enter network configuration mode.</p><img loading="lazy" height="446" width="500" src="'+s+'" class="common_img" style="width:400px;"></li><li><p>Use a computer to search for the corresponding Wi-Fi hotspot and click <strong>Connect</strong>.</p><img loading="lazy" height="189" width="359" src="'+ct+'" class="common_img" style="width:400px;"><img loading="lazy" height="138" width="358" src="'+gt+'" class="common_img" style="width:400px;"></li><li><p>Open a web browser, enter <strong><a href="http://192.168.4.1" target="_blank" rel="noreferrer">http://192.168.4.1</a></strong>, or click the <a href="http://192.168.4.1/" target="_blank" rel="noreferrer">Network Configuration</a> link directly.</p><img loading="lazy" height="621" width="955" src="'+c+'" class="common_img" style="width:800px;"></li><li><p>Click the language dropdown in the top-right corner to switch the display language to <strong>English</strong>.</p><img loading="lazy" height="205" width="940" src="'+g+'" class="common_img" style="width:800px;"></li><li><p>Enter the target Wi-Fi name in the <strong>SSID:</strong> field labeled ①, and enter the Wi-Fi password in the <strong>Password:</strong> field labeled ②. Click <strong>Connect</strong> labeled ③. The module will search for the matching network and connect.</p><img loading="lazy" height="236" width="936" src="'+d+'" class="common_img" style="width:800px;"></li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p><strong>Do not enter credentials for Wi-Fi networks that cannot be found, have weak signals, or lack internet access.</strong></p></li><li><p><strong>If the module has previously saved credentials for other Wi-Fi networks, newly saved credentials will coexist with them. On subsequent startups, the module attempts to match and connect to saved networks sequentially in the order they were stored.</strong></p></li></ul></div><ol start="6"><li>If the notification <strong>Failed to connect to the Access Point</strong> appears, the hotspot could not be found, or the password was incorrect. Re-enter the credentials.</li></ol><img loading="lazy" height="279" width="958" src="'+p+'" class="common_img" style="width:800px;"><ol start="7"><li>If the success checkmark and the message <strong>Device will restart in 0 seconds</strong> appear, the module has successfully connected to the hotspot. The module will automatically restart and connect to the network. This completes the preliminary network setup, allowing subsequent features of the WonderLLM AI module to be explored.</li></ol><img loading="lazy" height="304" width="640" src="'+h+'" class="common_img" style="width:800px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>If the screen displays an error message such as &quot;Failed to check for new version, retrying in xx seconds&quot; after network configuration, the current hotspot may lack internet access or have poor signal quality. Switch to a different Wi-Fi network.</strong></p></div><h3 id="_2-2-3-device-binding" tabindex="-1">2.2.3 Device Binding <a class="header-anchor" href="#_2-2-3-device-binding" aria-label="Permalink to &quot;2.2.3 Device Binding&quot;">​</a></h3><h4 id="_2-2-3-1-device-id" tabindex="-1">2.2.3.1 Device ID <a class="header-anchor" href="#_2-2-3-1-device-id" aria-label="Permalink to &quot;2.2.3.1 Device ID&quot;">​</a></h4><p>This section explains how to bind the device using its 6-digit Device ID.</p><ol><li><p>After network configuration, upon first-time startup, the screen displays a <strong>6-digit Device ID</strong> and the <strong>device binding platform URL</strong>, accompanied by a voice announcement. Follow the instructions below to bind the module to an agent on the platform.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p><strong>After completing account registration, bind the device to the default agent or create a new agent to bind with.</strong></p></li><li><p><strong>The following guide details two binding methods: quick binding and new agent binding.</strong></p></li></ul></div><img loading="lazy" height="1773" width="2364" src="'+m+'" class="common_img" style="width:400px;"></li></ol><hr><h4 id="_2-2-3-2-quick-binding" tabindex="-1">2.2.3.2 Quick Binding <a class="header-anchor" href="#_2-2-3-2-quick-binding" aria-label="Permalink to &quot;2.2.3.2 Quick Binding&quot;">​</a></h4>',38)),e("ol",null,[t[8]||(t[8]=i('<li><p>Open a web browser, go to <strong><a href="https://xiaozhi.me" target="_blank" rel="noreferrer">https://xiaozhi.me</a></strong>, or click <a href="https://xiaozhi.me/" target="_blank" rel="noreferrer">XiaoZhi AI</a> to visit directly.</p><img loading="lazy" height="544" width="957" src="'+u+'" class="common_img" style="width:800px;"></li><li><p>Click the language selector in the upper-right corner to switch the display language to <strong>English</strong>.</p><img loading="lazy" height="447" width="960" src="'+A+'" class="common_img" style="width:800px;"></li><li><p>Click <strong>Console</strong> to access the XiaoZhi AI platform management console.</p><img loading="lazy" height="423" width="957" src="'+w+'" class="common_img" style="width:800px;"></li><li><p>A platform account is required for first-time login. Account registration can be completed directly on the login page via email or third-party authentication.</p><img loading="lazy" height="1040" width="1920" src="'+y+'" class="common_img" style="width:800px;"></li><li><p>Click the dropdown arrow labeled ① next to <strong>Add Device</strong> and select <strong>Create Agent</strong> labeled ②.</p><img loading="lazy" height="574" width="956" src="'+f+'" class="common_img" style="width:800px;"></li><li><p>In the pop-up prompt, enter the desired agent name and click <strong>Confirm</strong>.</p></li><li><p>Click <strong>Configure Role</strong> on the agent card.</p><img loading="lazy" height="534" width="958" src="'+x+'" class="common_img" style="width:800px;"></li>',7)),e("li",null,[t[4]||(t[4]=e("p",null,[o("In the configuration interface, enter "),e("strong",null,"Hello Hiwonder"),o(" as the assistant nickname in field ①. "),e("strong",null,"Modification is not recommended"),o(". If changes are required, refer to "),e("a",{href:"./.html"},"1.10 Wake Word Modification"),o(" and update the module wake word accordingly.")],-1)),t[5]||(t[5]=e("p",null,"In field ②, select the dialogue language and voice role as required.",-1)),t[6]||(t[6]=e("p",null,"In field ③, use the default role description or a custom description. The role description provided below is recommended to ensure smoother interactions and better compatibility with subsequent features:",-1)),e("div",pt,[t[0]||(t[0]=e("p",{class:"custom-block-title"},"NOTE",-1)),t[1]||(t[1]=e("p",null,null,-1)),t[2]||(t[2]=e("p",null,[e("strong",null,"[Role Definition]")],-1)),e("p",null,[e("strong",null,"You are "+E(n.assistant_name)+", an intelligent assistant with a physical presence.",1)]),t[3]||(t[3]=i("<p><strong>Execute various tasks and follow instructions accurately.</strong></p><p><strong>[Core Characteristics]</strong></p><ul><li><p><strong>Understand intent accurately</strong></p></li><li><p><strong>Provide concise responses without unnecessary details</strong></p></li><li><p><strong>Do not store any memory</strong></p></li><li><p><strong>Offer appropriate suggestions and execute them accordingly</strong></p></li></ul>",3))]),t[7]||(t[7]=e("img",{loading:"lazy",height:"682",width:"941",src:r,class:"common_img",style:{width:"800px"}},null,-1))]),t[9]||(t[9]=i('<li><p>Set <strong>Language Model</strong> to <strong>DeepSeek V3.1 (Powerful)</strong>. Adjust advanced parameters if required, or keep the default settings and click <strong>Save</strong>.</p><img loading="lazy" height="332" width="802" src="'+b+'" class="common_img" style="width:800px;"></li><li><p>After saving the configuration, return to the previous interface and click <strong>Add Device</strong>.</p><img loading="lazy" height="528" width="954" src="'+v+'" class="common_img" style="width:800px;"></li><li><p>In the pop-up window, enter the 6-digit verification code announced by the device into the <strong>Verification Code:</strong> input field, and click <strong>Confirm</strong> to complete device binding.</p><img loading="lazy" height="463" width="952" src="'+z+'" class="common_img" style="width:800px;"></li><li><p>Once binding succeeds, the prompt <strong>Device added successfully</strong> appears on the page. Select <strong>Open Source</strong> and click <strong>Start Using</strong>.</p><img loading="lazy" height="906" width="956" src="'+D+'" class="common_img" style="width:800px;"></li>',4))]),t[11]||(t[11]=i('<h3 id="_2-2-4-module-functional-verification" tabindex="-1">2.2.4 Module Functional Verification <a class="header-anchor" href="#_2-2-4-module-functional-verification" aria-label="Permalink to &quot;2.2.4 Module Functional Verification&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p><strong>When interacting with the large AI model, specific phrasing is not strictly required. Commands can be phrased freely as long as the core intent remains consistent, enabling the model to understand and respond.</strong></p></li><li><p><strong>After completing network configuration and device binding, always restart both the robot and the module before performing functional verification.</strong></p></li></ul></div><ol><li><p>Say the wake word <strong>Hello Hiwonder</strong> to activate the module.</p><img loading="lazy" height="1908" width="2544" src="'+_+'" class="common_img" style="width:500px;"></li><li><p>Ask about the weather, such as <strong>&quot;Switch your city to New York&quot;</strong> or <strong>&quot;What is the weather today?&quot;</strong>.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>When interacting with the large AI model, strict adherence to the sample command is unnecessary. Natural phrasing is fully supported as long as the underlying intent is communicated clearly.</strong></p></div><img loading="lazy" height="1908" width="2544" src="'+C+'" class="common_img" style="width:500px;"></li></ol>',3))])}const vt=k(dt,[["render",ht]]);export{bt as __pageData,vt as default};
